/**
 * managerLabels.js — the single source of truth for manager label text.
 *
 * Every bilingual label used by `src/components/configs` and
 * `src/components/labels` is registered here exactly once. The old files now
 * reference `L.key` (lowercase en/cn) or `LU.key` (uppercase EN/CN) instead
 * of re-declaring the same translation hundreds of times.
 *
 * Add a new translation ONCE here, then reference it:
 *   import { L } from "@/components/labels/managerLabels";
 *   title: L.title
 *
 * This file is generated from the existing labels; edit by hand when a label
 * needs a new wording, and keep the key stable so consumers do not break.
 */

