// Labels are shared across every manager screen; freeze them so one screen
// cannot accidentally mutate another screen's copy.
Object.values(L).forEach(Object.freeze);
Object.freeze(L);

/** Uppercase-key view (EN/CN) for PAGE_TEXT-style objects. */
export const LU = Object.freeze(
  Object.fromEntries(
    Object.entries(L).map(([key, value]) => [key, Object.freeze({ EN: value.en, CN: value.cn })])
  )
);

/** The legacy "English / 中文" string for a registry pair. */
export const bilingual = (pair) => `${pair.en} / ${pair.cn}`;

/** A single language value from a registry key. */
export const getLabel = (key, language = 'en') => {
  const entry = L[key];
  if (!entry) return key;
  return language === 'cn' || language === 'CN' ? entry.cn : entry.en;
};

/** The raw { en, cn } pair for a registry key (or null). */
export const getLabelPair = (key) => L[key] || null;

